arguments.command:
cd /tmp/vally-eval-trial-TPlC16 && cat > src/CheckoutPricing.Application/CheckoutCalculator.cs <<'E'
namespace CheckoutPricing.Application;

public static class CheckoutCalculator
{
    public static decimal CalculatePayableTotal(string customerTier, decimal subtotal) => subtotal;
}
E
cat > tests/CheckoutPricing.UnitTests/LoyaltyDiscountTests.cs <<'E'
using CheckoutPricing.Application;

namespace CheckoutPricing.UnitTests;

public class LoyaltyDiscountTests
{
    [Fact]
    public void Gold_customer_with_subtotal_100_pays_95()
    {
        Assert.Equal(95.00m, CheckoutCalculator.CalculatePayableTotal("Gold", 100.00m));
    }
}
E
dotnet test tests/CheckoutPricing.UnitTests 2>&1 | grep -E "error|Assert|Expected|Actual|Failed|Passed" | head

